// Images are embedded so this portfolio needs only three files.
window.PORTFOLIO_MEDIA = {"assets/paul-avatar.png":"data:image/png;base64,","assets/paul-original.jpg":"data:image/jpeg;base64,","assets/certificates/cert-1.jpg":"data:image/jpeg;base64,","assets/certificates/cert-10.jpg":"data:image/jpeg;base64,","assets/certificates/cert-11.jpg":"data:image/jpeg;base64,","assets/certificates/cert-12.jpg":"data:image/jpeg;base64,","assets/certificates/cert-13.jpg":"data:image/jpeg;base64,","assets/certificates/cert-14.jpg":"data:image/jpeg;base64,","assets/certificates/cert-2.jpg":"data:image/jpeg;base64,","assets/certificates/cert-3.jpg":"data:image/jpeg;base64,","assets/certificates/cert-4.jpg":"data:image/jpeg;base64,","assets/certificates/cert-5.jpg":"data:image/jpeg;base64,","assets/certificates/cert-6.jpg":"data:image/jpeg;base64,","assets/certificates/cert-7.jpg":"data:image/jpeg;base64,","assets/certificates/cert-8.jpg":"data:image/jpeg;base64,","assets/certificates/cert-9.jpg":"data:image/jpeg;base64,","assets/certificates/data-analysis-using-python.png":"data:image/png;base64,"};
window.CERTIFICATES.forEach(record => {
  record.imageFormat = record.src.endsWith('.png') ? 'PNG' : 'JPEG';
  record.src = window.PORTFOLIO_MEDIA[record.src];
});
document.getElementById('hero-portrait').src = window.PORTFOLIO_MEDIA['assets/paul-avatar.png'];


(() => {
  'use strict';
  const $ = (selector) => document.querySelector(selector);
  const records = window.CERTIFICATES || [];
  const profile = window.PORTFOLIO_PROFILE || {};
  const icons = (name, className = '') => `<svg class="${className}" aria-hidden="true"><use href="#${name}"/></svg>`;
  let toastTimer;
  function toast(message) {
    $('#toast').textContent = message;
    $('#toast').classList.add('visible');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => $('#toast').classList.remove('visible'), 3200);
  }
  $('#year').textContent = new Date().getFullYear();

  // Motion always respects the visitor's system preference, with a manual override.
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  let savedMotion = null;
  try { savedMotion = localStorage.getItem('paul-motion'); } catch (_) {}
  let motionPaused = savedMotion === null ? reducedMotion.matches : savedMotion === 'paused';
  function updateMotion() {
    document.documentElement.classList.toggle('motion-paused', motionPaused);
    $('#motion-toggle').setAttribute('aria-pressed', String(motionPaused));
    $('#motion-toggle').setAttribute('aria-label', motionPaused ? 'Play animations' : 'Pause animations');
    $('#motion-toggle').innerHTML = icons(motionPaused ? 'play' : 'pause');
  }
  updateMotion();
  $('#motion-toggle').addEventListener('click', () => {
    motionPaused = !motionPaused;
    updateMotion();
    try { localStorage.setItem('paul-motion', motionPaused ? 'paused' : 'playing'); } catch (_) {}
    toast(motionPaused ? 'Animations paused.' : 'Animations playing.');
  });
  reducedMotion.addEventListener('change', (event) => {
    if (savedMotion === null) { motionPaused = event.matches; updateMotion(); }
  });

  const portraitStage = $('#portrait-stage');
  const pointerCapable = window.matchMedia('(hover: hover) and (pointer: fine)');
  $('.hero').addEventListener('pointermove', (event) => {
    if (motionPaused || reducedMotion.matches || !pointerCapable.matches) return;
    const bounds = portraitStage.getBoundingClientRect();
    const x = Math.max(-1, Math.min(1, (event.clientX - bounds.left - bounds.width / 2) / bounds.width));
    const y = Math.max(-1, Math.min(1, (event.clientY - bounds.top - bounds.height / 2) / bounds.height));
    portraitStage.style.setProperty('--ry', `${x * 5}deg`);
    portraitStage.style.setProperty('--rx', `${-y * 3}deg`);
  });
  $('.hero').addEventListener('pointerleave', () => {
    portraitStage.style.setProperty('--ry', '0deg');
    portraitStage.style.setProperty('--rx', '0deg');
  });
  let originalPortrait = false;
  $('#portrait-switch').addEventListener('click', () => {
    originalPortrait = !originalPortrait;
    portraitStage.classList.toggle('original', originalPortrait);
    $('#hero-portrait').src = originalPortrait ? window.PORTFOLIO_MEDIA['assets/paul-original.jpg'] : window.PORTFOLIO_MEDIA['assets/paul-avatar.png'];
    $('#hero-portrait').alt = originalPortrait ? 'Original formal photograph of Paul Angelo Hernandez' : 'Illustrated portrait of Paul Angelo Hernandez wearing a dark suit';
    $('#portrait-switch').setAttribute('aria-pressed', String(originalPortrait));
    $('#portrait-switch-label').textContent = originalPortrait ? 'View illustrated portrait' : 'View original photo';
  });

  const menuToggle = $('.menu-toggle');
  function closeMenu() {
    $('#mobile-nav').hidden = true;
    menuToggle.setAttribute('aria-expanded', 'false');
    menuToggle.setAttribute('aria-label', 'Open navigation');
    menuToggle.innerHTML = icons('menu');
  }
  menuToggle.addEventListener('click', () => {
    const opened = menuToggle.getAttribute('aria-expanded') !== 'true';
    $('#mobile-nav').hidden = !opened;
    menuToggle.setAttribute('aria-expanded', String(opened));
    menuToggle.setAttribute('aria-label', opened ? 'Close navigation' : 'Open navigation');
    menuToggle.innerHTML = icons(opened ? 'close' : 'menu');
  });
  $('#mobile-nav').querySelectorAll('a').forEach(a => a.addEventListener('click', closeMenu));
  document.addEventListener('click', (event) => { if (!event.composedPath().includes($('.site-header'))) closeMenu(); });
  document.addEventListener('keydown', (event) => { if (event.key === 'Escape') closeMenu(); });
  window.matchMedia('(min-width: 801px)').addEventListener('change', (event) => { if (event.matches) closeMenu(); });

  // A varied first view; every supplied record remains available through the gallery.
  const featuredIds = ['cert-11', 'cert-2', 'cert-10', 'cert-13', 'cert-14', 'cert-1'];
  const ordered = [...featuredIds.map(id => records.find(record => record.id === id)).filter(Boolean), ...records.filter(record => !featuredIds.includes(record.id))];
  const categories = ['All', 'JavaScript', 'SQL', 'Data Analytics', 'Networking', 'Badge'];
  let category = 'All';
  let query = '';
  let visibleLimit = 6;
  let filtered = ordered;
  let currentIndex = 0;
  const dateLabel = value => value ? new Intl.DateTimeFormat('en', { month: 'short', year: 'numeric', timeZone: 'UTC' }).format(new Date(`${value}T00:00:00Z`)) : 'Badge artwork';
  categories.forEach(value => {
    const count = value === 'All' ? records.length : records.filter(record => record.category === value).length;
    if (!count) return;
    const button = document.createElement('button');
    button.className = 'filter-button';
    button.dataset.category = value;
    button.setAttribute('aria-pressed', String(value === category));
    button.textContent = value === 'All' ? 'All records' : value === 'Badge' ? 'Badges' : value;
    const countSpan = document.createElement('span');
    countSpan.textContent = String(count);
    countSpan.setAttribute('aria-hidden', 'true');
    button.append(countSpan);
    button.addEventListener('click', () => { category = value; visibleLimit = 6; renderGallery(); });
    $('#filter-list').append(button);
  });
  function renderGallery() {
    filtered = ordered.filter(record => (category === 'All' || record.category === category) && `${record.title} ${record.issuer} ${record.category}`.toLowerCase().includes(query));
    const grid = $('#certificate-grid');
    grid.replaceChildren();
    filtered.slice(0, visibleLimit).forEach(record => {
      const card = document.createElement('button');
      card.className = 'certificate-card';
      card.setAttribute('aria-label', `View ${record.title} by ${record.issuer}`);
      const imageWrap = document.createElement('div');
      imageWrap.className = 'certificate-image';
      const image = document.createElement('img');
      image.src = record.src;
      image.alt = record.alt;
      image.loading = 'lazy';
      image.decoding = 'async';
      image.draggable = false;
      const zoom = document.createElement('span');
      zoom.className = 'certificate-zoom';
      zoom.innerHTML = icons('plus');
      imageWrap.append(image, zoom);
      const meta = document.createElement('div');
      meta.className = 'certificate-card-meta';
      const topic = document.createElement('span');
      topic.textContent = record.category;
      const date = document.createElement(record.date ? 'time' : 'span');
      if (record.date) date.dateTime = record.date;
      date.textContent = dateLabel(record.date);
      meta.append(topic, date);
      const title = document.createElement('h3');
      title.textContent = record.title.replace(' (additional copy)', '').replace(' - badge artwork (PNG)', '').replace(' - badge artwork', '');
      const issuer = document.createElement('p');
      issuer.className = 'issuer';
      issuer.textContent = record.issuer;
      card.append(imageWrap, meta, title, issuer);
      if (record.title.includes('additional copy') || record.category === 'Badge') {
        const note = document.createElement('span');
        note.className = 'record-note';
        note.textContent = record.category === 'Badge' ? `Badge artwork · ${record.imageFormat === 'PNG' ? 'PNG' : 'JPEG'}` : 'Additional supplied copy';
        card.append(note);
      }
      card.addEventListener('click', () => openViewer(record.id));
      grid.append(card);
    });
    const shown = Math.min(visibleLimit, filtered.length);
    $('#result-count').textContent = `Showing ${shown} of ${filtered.length} ${filtered.length === 1 ? 'record' : 'records'}`;
    $('#empty-state').hidden = filtered.length !== 0;
    $('#show-more').hidden = shown >= filtered.length;
    $('#show-more').innerHTML = `Show all ${filtered.length} records ${icons('plus')}`;
    $('#clear-filters').hidden = category === 'All' && query === '';
    $('#filter-list').querySelectorAll('button').forEach(button => button.setAttribute('aria-pressed', String(button.dataset.category === category)));
  }
  $('#certificate-search').addEventListener('input', event => { query = event.target.value.trim().toLowerCase(); visibleLimit = 6; renderGallery(); });
  $('#show-more').addEventListener('click', () => {
    const previousLimit = visibleLimit;
    visibleLimit = filtered.length;
    renderGallery();
    const nextCard = $('#certificate-grid').children[previousLimit];
    if (nextCard) nextCard.focus({preventScroll: true});
  });
  $('#clear-filters').addEventListener('click', () => {
    category = 'All'; query = ''; visibleLimit = 6;
    $('#certificate-search').value = '';
    renderGallery();
    $('#filter-list button').focus({preventScroll:true});
  });
  document.querySelectorAll('[data-focus]').forEach(link => link.addEventListener('click', () => {
    category = link.dataset.focus; query = ''; visibleLimit = 6;
    $('#certificate-search').value = '';
    renderGallery();
  }));
  renderGallery();

  const dialog = $('#certificate-dialog');
  let previousOverflow = '';
  function updateViewer() {
    const record = filtered[currentIndex];
    if (!record) return;
    $('#viewer-title').textContent = record.title;
    $('#viewer-category').textContent = record.category;
    $('#viewer-details').textContent = `${record.issuer} · ${record.date ? new Intl.DateTimeFormat('en', {dateStyle:'long',timeZone:'UTC'}).format(new Date(`${record.date}T00:00:00Z`)) : 'Supplied badge artwork — no holder name or date shown'}`;
    $('#viewer-image').src = record.src;
    $('#viewer-image').alt = record.alt;
    $('#viewer-position').textContent = `${currentIndex + 1} / ${filtered.length}`;
    $('#viewer-prev').disabled = filtered.length < 2;
    $('#viewer-next').disabled = filtered.length < 2;
  }
  function openViewer(id) {
    currentIndex = filtered.findIndex(record => record.id === id);
    updateViewer();
    previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    dialog.showModal();
    $('#viewer-close').focus();
  }
  function changeRecord(direction) { currentIndex = (currentIndex + direction + filtered.length) % filtered.length; updateViewer(); }
  $('#viewer-close').addEventListener('click', () => dialog.close());
  $('#viewer-next').addEventListener('click', () => changeRecord(1));
  $('#viewer-prev').addEventListener('click', () => changeRecord(-1));
  dialog.addEventListener('click', event => { if (event.target === dialog) dialog.close(); });
  dialog.addEventListener('close', () => { document.body.style.overflow = previousOverflow; });
  dialog.addEventListener('keydown', event => {
    if (event.key === 'ArrowRight') { event.preventDefault(); changeRecord(1); }
    if (event.key === 'ArrowLeft') { event.preventDefault(); changeRecord(-1); }
  });

  async function sharePortfolio() {
    const url = location.protocol === 'https:' || location.protocol === 'http:' ? `${location.origin}${location.pathname}` : 'https://paul-angelo-hernandez-portfolio.genialbison18.chatgpt.site';
    try {
      if (navigator.share) { await navigator.share({title: 'Paul Hernandez — Personal Portfolio', text: 'Explore my journey in code, data, and technology.', url}); return; }
      if (navigator.clipboard && window.isSecureContext) { await navigator.clipboard.writeText(url); toast('Portfolio link copied.'); return; }
      const field = document.createElement('textarea');
      field.value = url; field.style.position = 'fixed'; field.style.opacity = '0'; document.body.append(field); field.select();
      const copied = document.execCommand('copy'); field.remove();
      toast(copied ? 'Portfolio link copied.' : 'Use your browser address bar to share this portfolio.');
    } catch (error) { if (error.name !== 'AbortError') toast('Use your browser address bar to share this portfolio.'); }
  }
  document.querySelectorAll('.share-button').forEach(button => button.addEventListener('click', sharePortfolio));
  const contactActions = $('#connect-actions');
  const contacts = [
    {label:'Email me',url:profile.email ? `mailto:${profile.email}` : '',icon:'mail'},
    {label:'GitHub',url:profile.github,icon:'arrow'},
    {label:'LinkedIn',url:profile.linkedin,icon:'arrow'},
    {label:'Facebook',url:profile.facebook,icon:'arrow'}
  ].filter(contact => contact.url && (/^https:\/\//.test(contact.url) || contact.url.startsWith('mailto:')));
  if (contacts.length) {
    $('#connect-description').textContent = "Have an idea or want to say hello? Let's start a conversation.";
    contacts.forEach((contact, index) => {
      const link = document.createElement('a');
      link.className = index === 0 ? 'glass glass-primary' : 'text-link';
      link.href = contact.url;
      if (!contact.url.startsWith('mailto:')) { link.target = '_blank'; link.rel = 'noopener noreferrer'; }
      link.append(document.createTextNode(contact.label));
      const orb = document.createElement('span'); orb.className = index === 0 ? 'button-orb' : ''; orb.innerHTML = icons(contact.icon); link.append(orb);
      contactActions.append(link);
    });
  }

  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver(entries => entries.forEach(entry => {
      if (entry.isIntersecting) { entry.target.classList.remove('is-waiting'); observer.unobserve(entry.target); }
    }), {threshold: .08, rootMargin: '0px 0px 25px 0px'});
    document.querySelectorAll('.reveal').forEach(element => {
      if (!reducedMotion.matches && !motionPaused) element.classList.add('is-waiting');
      observer.observe(element);
    });
    const navObserver = new IntersectionObserver(entries => entries.forEach(entry => {
      if (entry.isIntersecting) document.querySelectorAll('.desktop-nav a').forEach(link => link.classList.toggle('active', link.hash === `#${entry.target.id}`));
    }), {rootMargin: '-15% 0px -65% 0px',threshold:0});
    ['home','about','certificates','connect'].forEach(id => navObserver.observe(document.getElementById(id)));
  }
  // Courtesy deterrents only. Browser developer tools cannot be securely disabled by a website.
  document.addEventListener('contextmenu', event => {
    if (event.target.closest('input, textarea, [contenteditable="true"]')) return;
    event.preventDefault(); toast('Right-click is disabled on this portfolio.');
  });
  document.addEventListener('dragstart', event => { if (event.target.tagName === 'IMG') event.preventDefault(); });
  document.addEventListener('keydown', event => {
    const key = event.key.toLowerCase();
    if (event.key === 'F12' || ((event.ctrlKey || event.metaKey) && event.shiftKey && ['i','j','c'].includes(key)) || ((event.ctrlKey || event.metaKey) && key === 'u')) {
      event.preventDefault(); toast('This shortcut is disabled on this portfolio.');
    }
  });
})();
